review_comments:
These functions should not use special handling - this seems like a work-around for another work-around in `src/function/function_binder.cpp` where we don't return the output type but convert it to `SQLNULL` as a fallback.

Can we apply this diff to fix that, and turn this back into `DEFAULT_NULL_HANDLING`

```diff
diff --git a/src/function/function_binder.cpp b/src/function/function_binder.cpp
index 267f589d8f..87eacee685 100644
--- a/src/function/function_binder.cpp
+++ b/src/function/function_binder.cpp
@@ -306,13 +306,20 @@ unique_ptr<Expression> FunctionBinder::BindScalarFunction(ScalarFunctionCatalogE
        LogicalType return_type_if_null;
        switch (bound_function.return_type.id()) {
        case LogicalTypeId::ANY:
+               return_type_if_null = LogicalType::SQLNULL;
+               break;
        case LogicalTypeId::DECIMAL:
        case LogicalTypeId::STRUCT:
        case LogicalTypeId::LIST:
        case LogicalTypeId::MAP:
        case LogicalTypeId::UNION:
        case LogicalTypeId::ARRAY:
-               return_type_if_null = LogicalType::SQLNULL;
+               if (bound_function.return_type.AuxInfo()) {
+                       // this is a complete and valid type - return it
+                       return_type_if_null = bound_function.return_type;
+               } else {
+                       return_type_if_null = LogicalType::SQLNULL;
+               }
                break;
        default:
                return_type_if_null = bound_function.return_type;

```
